def init_crc64() -> None:
    if CRC64_TABLE:
        return
    for i in range(256):
        crc = i
        for _ in range(8):
            if crc & 1:
                crc = (crc >> 1) ^ CRC64_POLY
            else:
                crc >>= 1
        CRC64_TABLE.append(crc & 0xFFFFFFFFFFFFFFFF)


